					{
						example: "\"me and you and her\".split(\"and\")",
						evaluated: "['me ', ' you ', ' her']"
					},
					{
						example: "\"me? you, and her\".split(/[ ,?]+/)",
						evaluated: "['me', 'you', 'and', 'her']",
						description: "Split one or more of space, comma and '?' using a regular expression"
					}
